INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Entscheidungstabelle nur für komplexe Entscheidungen sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Logik klärbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Entscheidungstabelle?', 3, '[{"text": "Logische Entscheidungen strukturieren", "correct": true, "because": "Bedingungen und Aktionen klar"}, {"text": "Datenfluss zeigen", "correct": false, "because": "Datenflussdiagramm-Thema"}, {"text": "UI gestalten", "correct": false, "because": "Kein Designaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Entscheidungstabelle?', 5, '[{"text": "Bedingungen", "correct": true, "because": "Definieren Entscheidungskriterien"}, {"text": "Aktionen", "correct": true, "because": "Zeigen Ergebnisse"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Entscheidungstabellen zeigen Bedingungen. b) Sie ersetzen Programmablaufpläne.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alternative, kein Ersatz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Entscheidungstabelle?', 4, '[{"text": "Bedingungen", "correct": false, "because": "Kern der Logik"}, {"text": "Aktionen", "correct": false, "because": "Ergebnisse der Entscheidung"}, {"text": "UI-Design", "correct": true, "because": "Kein Entscheidungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Entscheidungstabelle auch Abläufe zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Logik, nicht Reihenfolge"}, {"text": "Ja", "correct": false, "because": "Abläufe in anderen Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine Bedingung?', 3, '[{"text": "Tabellenzeile", "correct": true, "because": "Zeigt Bedingungsstatus"}, {"text": "Pfeil", "correct": false, "because": "Ablaufdiagramm"}, {"text": "Rechteck", "correct": false, "because": "Prozessschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten verbessern eine Entscheidungstabelle?', 5, '[{"text": "Bedingungskombinationen", "correct": true, "because": "Vollständige Logik"}, {"text": "Aktionseinträge", "correct": true, "because": "Ergebnisse definieren"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Entscheidungstabellen zeigen logische Entscheidungen. b) Sie sind für Hardwareplanung wichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Entscheidungstabelle?', 4, '[{"text": "Bedingungen", "correct": false, "because": "Grundlage der Logik"}, {"text": "Aktionen", "correct": false, "because": "Zeigen Ergebnisse"}, {"text": "Netzwerkknoten", "correct": true, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Entscheidungstabelle nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftslogik"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen zeigt eine Entscheidungstabelle?', 4, '[{"text": "Bedingungskombinationen", "correct": true, "because": "Logische Verknüpfungen"}, {"text": "Aktionszuweisungen", "correct": true, "because": "Ergebnisse darstellen"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Entscheidungstabellen nur für Entwickler sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Analysten"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Entscheidungstabelle?', 3, '[{"text": "Logische Vollständigkeit", "correct": true, "because": "Alle Fälle abdecken"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Visuelle Effekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Entscheidungstabellen zeigen Bedingungen und Aktionen. b) Sie ersetzen ERDs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ERDs für Datenstruktur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Entscheidungstabelle?', 5, '[{"text": "Logikübersicht", "correct": true, "because": "Klarheit über Entscheidungen"}, {"text": "Testfallbasis", "correct": true, "because": "Alle Kombinationen sichtbar"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Hardwareplanung", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in einer Entscheidungstabelle unwichtig?', 3, '[{"text": "Bedingungsstatus", "correct": false, "because": "Kern der Logik"}, {"text": "Aktionseinträge", "correct": false, "because": "Ergebnisse definieren"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Entscheidungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt eine Entscheidungstabelle auch Abläufe?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Logik"}, {"text": "Ja", "correct": false, "because": "Abläufe in anderen Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Entscheidungstabellen für Tests nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Testfälle ableitbar"}, {"text": "Nein", "correct": false, "because": "Logikbasis für Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine Aktion?', 4, '[{"text": "Tabellenspalte", "correct": true, "because": "Zeigt Ergebnisse"}, {"text": "Pfeil", "correct": false, "because": "Ablaufdiagramm"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}]');
